const input = $input.first().json;
const VERSION = '1.0';
const MAX_TEXT = 4096;
const correlationId = typeof input.correlationId === 'string' && /^[A-Za-z0-9._:-]{1,128}$/.test(input.correlationId) ? input.correlationId : crypto.randomUUID();
const testMode = input.testMode !== false || input.profileTestMode !== false;
const draftOnly = input.draftOnly !== false || input.profileDraftOnly !== false;
const base = {contractVersion:VERSION,correlationId,testMode,draftOnly,sendAuthorized:false};
const result = (ok,status,extra={}) => [{json:{...base,ok,status,...extra}}];
const fail = (code,message) => result(false,'rejected',{error:{code,message,retryable:false}});
const allowedFields = new Set(['contractVersion','correlationId','testMode','draftOnly','idempotencyKey','chatId','text','format','disableNotification','profileAllowedChatIds','profileTestMode','profileDraftOnly']);
if (!input || Array.isArray(input) || typeof input !== 'object' || Object.keys(input).some((key) => !allowedFields.has(key))) return fail('INVALID_REQUEST','Input contains unknown fields');
if (input.contractVersion !== undefined && input.contractVersion !== VERSION) return fail('UNSUPPORTED_CONTRACT','contractVersion must be 1.0');
if (typeof input.idempotencyKey !== 'string' || !/^[A-Za-z0-9._:-]{8,128}$/.test(input.idempotencyKey)) return fail('INVALID_IDEMPOTENCY_KEY','A stable idempotencyKey is required');
if (typeof input.chatId !== 'string' || !/^-?[1-9][0-9]{4,19}$/.test(input.chatId)) return fail('INVALID_CHAT_ID','chatId must be a numeric Telegram chat ID');
const format = input.format ?? 'plain';
if (format !== 'plain') return fail('UNSUPPORTED_FORMAT','Only plain text is supported; HTML and Markdown are rejected');
if (typeof input.text !== 'string' || input.text.length < 1 || input.text.length > MAX_TEXT || /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/.test(input.text)) return fail('INVALID_MESSAGE_TEXT','text must contain 1..4096 characters without control bytes');
if (input.disableNotification !== undefined && typeof input.disableNotification !== 'boolean') return fail('INVALID_NOTIFICATION_MODE','disableNotification must be boolean');
const configured = typeof input.profileAllowedChatIds === 'string' ? input.profileAllowedChatIds.split(/[\s,;]+/).filter(Boolean) : [];
if (!configured.length || configured.includes('REPLACE_WITH_ALLOWED_CHAT_IDS') || configured.some((chatId) => !/^-?[1-9][0-9]{4,19}$/.test(chatId))) return fail('ALLOWLIST_NOT_CONFIGURED','Configure numeric chat IDs in Telegram Safety Profile');
const allowlist = new Set(configured);
if (!allowlist.has(input.chatId)) return fail('CHAT_NOT_ALLOWED','Target chat is not present in the workflow allowlist');
const chatRef = `...${input.chatId.slice(-4)}`;
if (testMode) return result(true,'preview',{reason:'TEST_MODE',idempotencyKey:input.idempotencyKey,chatRef,messageLength:input.text.length});
if (draftOnly) return result(true,'draft',{reason:'DRAFT_ONLY',idempotencyKey:input.idempotencyKey,chatRef,messageLength:input.text.length});
const state = $getWorkflowStaticData('global');
state.telegramSendReservations = state.telegramSendReservations && typeof state.telegramSendReservations === 'object' ? state.telegramSendReservations : {};
const now = Date.now();
const maxAge = 7 * 24 * 60 * 60 * 1000;
for (const [key,value] of Object.entries(state.telegramSendReservations)) if (!value || !Number.isFinite(Date.parse(value.reservedAt)) || now - Date.parse(value.reservedAt) > maxAge) delete state.telegramSendReservations[key];
const storageKey = `key:${input.idempotencyKey}`;
if (Object.prototype.hasOwnProperty.call(state.telegramSendReservations,storageKey)) return result(true,'duplicate',{reason:'IDEMPOTENCY_KEY_ALREADY_RESERVED',idempotencyKey:input.idempotencyKey,chatRef});
const keys = Object.keys(state.telegramSendReservations);
if (keys.length >= 500) { keys.sort((a,b) => Date.parse(state.telegramSendReservations[a].reservedAt) - Date.parse(state.telegramSendReservations[b].reservedAt)); for (const key of keys.slice(0, keys.length - 499)) delete state.telegramSendReservations[key]; }
state.telegramSendReservations[storageKey] = {reservedAt:new Date(now).toISOString(),status:'reserved',chatRef};
return [{json:{...base,ok:true,status:'authorized',sendAuthorized:true,idempotencyKey:input.idempotencyKey,chatRef,messageLength:input.text.length,telegram:{chatId:input.chatId,text:input.text,disableNotification:input.disableNotification === true}}}];

const response = $input.first().json ?? {};
const context = $('Validate Telegram Send Contract').first().json;
const statusCode = Number(response.error_code ?? response.statusCode ?? response.error?.httpCode ?? response.error?.statusCode ?? 0);
const description = [response.description,response.error_description,response.message,response.error?.message].find((value) => typeof value === 'string') ?? '';
const success = response.ok === true && Number.isInteger(response.result?.message_id);
let code = null;
if (!success) {
  if (statusCode === 401) code = 'AUTH_FAILED';
  else if (statusCode === 403 || (statusCode === 400 && /chat not found/i.test(description))) code = 'CHAT_FORBIDDEN';
  else if (statusCode === 429) code = 'RATE_LIMITED';
  else if (statusCode === 400 && /(parse|entit|format|markdown|html)/i.test(description)) code = 'FORMATTING_REJECTED';
  else if (statusCode === 400) code = 'REQUEST_REJECTED';
  else if (statusCode === 0 || statusCode >= 500) code = 'PROVIDER_UNAVAILABLE';
  else code = 'INVALID_PROVIDER_RESPONSE';
}
const retryAfterRaw = response.parameters?.retry_after ?? response.error?.context?.data?.parameters?.retry_after;
const retryAfter = Number.isInteger(Number(retryAfterRaw)) && Number(retryAfterRaw) >= 0 ? Number(retryAfterRaw) : null;
const state = $getWorkflowStaticData('global');
const storageKey = `key:${context.idempotencyKey}`;
if (state.telegramSendReservations && Object.prototype.hasOwnProperty.call(state.telegramSendReservations,storageKey)) state.telegramSendReservations[storageKey].status = success ? 'sent' : 'reconcile-required';
return [{json:{contractVersion:'1.0',correlationId:context.correlationId,ok:success,status:success?'sent':'failed',sendAuthorized:false,idempotencyKey:context.idempotencyKey,chatRef:context.chatRef,messageId:success?response.result.message_id:null,error:success?null:{code,httpStatus:statusCode||null,retryable:['RATE_LIMITED','PROVIDER_UNAVAILABLE'].includes(code),retryAfter,automaticRetry:false,reconcileRequired:['RATE_LIMITED','PROVIDER_UNAVAILABLE','INVALID_PROVIDER_RESPONSE'].includes(code)}}}];
